; Stream: header byte = volume (AY level) at the first note; then: note = 2 * pitch index,
;         length word (units: 1 beat = 600); rest = 0F0h, length word; 0E0h+n = volume n;
;         0FEh, address = loop; 0FFh = end (silence).

MUS_FM_INST0: equ 80	; OPLL instrument 5 for channel 0 (arpeggio)
MUS_FM_INST1: equ 224	; OPLL instrument 14 for channel 1 (bass)
MUS_STEP: equ 16		; units per 60 Hz tick (T96, 600 units per beat)

